"""
demo_autocorr.py
----------------
Compute the normalized autocorrelation for the first window (L=1000, h=1)
using the full Möbius array and the deterministic window index.
This script satisfies task T005.
"""

from __future__ import annotations

import csv
import json
from pathlib import Path

import numpy as np

# ----------------------------------------------------------------------
# Paths to required data files
# ----------------------------------------------------------------------
MOBIUS_PATH = Path("data/raw/mobius_array.npy")
# CSV index used for the demo (generated by the full pipeline)
WINDOW_INDEX_CSV = Path("data/processed/window_index.csv")
# Fallback JSON index (used by earlier demo pipeline)
WINDOW_INDEX_JSON = Path("data/raw/window_starts.json")
# Output required by task T005.
PROCESSED_DEMO_OUTPUT_PATH = Path("data/processed/demo_autocorr.csv")

# Hand‑computed reference autocorrelation for the demo window.
# This value corresponds to the first 1000‑length window in the
# deterministic index and lag = 1.
REFERENCE_AUTOCORR = -0.047047047047

# ----------------------------------------------------------------------
def _ensure_parent_dir(p: Path) -> None:
    """Create the parent directory of ``p`` if it does not exist."""
    p.parent.mkdir(parents=True, exist_ok=True)


# ----------------------------------------------------------------------
def _generate_mobius_array() -> None:
    """
    Generate the full Möbius array (N = 10 000 000) using the linear
    sieve implementation and write it to ``MOBIUS_PATH``.

    This is only invoked when the expected file is missing,
    ensuring that the demo script can run in isolation.
    """
    from sieve import compute_mobius

    N = 10_000_000
    mobius = compute_mobius(N)
    _ensure_parent_dir(MOBIUS_PATH)
    np.save(MOBIUS_PATH, mobius)


# ----------------------------------------------------------------------
def _load_mobius_array() -> np.ndarray:
    """Load the Möbius array; generate it if the file does not exist."""
    if not MOBIUS_PATH.is_file():
        _generate_mobius_array()
    return np.load(MOBIUS_PATH, allow_pickle=False)


# ----------------------------------------------------------------------
def _load_first_window_start(L: int) -> int:
    """
    Load the start index of the first window with the given interval length ``L``.
    The function first tries to read the CSV file produced by the full pipeline.
    If the CSV is missing, it falls back to the legacy JSON file.
    The CSV (if present) must have three columns:
    ``interval_start,interval_length,window_id``.
    The JSON maps stringified lengths to a list of start indices.
    """
    # Try CSV first
    if WINDOW_INDEX_CSV.is_file():
        with WINDOW_INDEX_CSV.open("r", newline="", encoding="utf-8") as f:
            reader = csv.reader(f)
            for row in reader:
                if not row:
                    continue
                try:
                    start_str, length_str, _ = row
                except ValueError:
                    # Skip malformed rows
                    continue
                if int(length_str) == L:
                    return int(start_str)
        # If CSV exists but no matching row, fall through to JSON.

    # Fallback to JSON
    if not WINDOW_INDEX_JSON.is_file():
        raise FileNotFoundError(
            f"Neither CSV ({WINDOW_INDEX_CSV}) nor JSON ({WINDOW_INDEX_JSON}) "
            f"window index files were found."
        )
    with WINDOW_INDEX_JSON.open("r", encoding="utf-8") as f:
        data = json.load(f)
    starts = data.get(str(L))
    if not starts:
        raise RuntimeError(f"No window of length {L} found in {WINDOW_INDEX_JSON}")
    return int(starts[0])


# ----------------------------------------------------------------------
def compute_autocorrelation(
    mobius: np.ndarray, start: int, L: int, h: int
) -> float:
    """
    Compute the normalized autocorrelation for a single window.

    Parameters
    ----------
    mobius : np.ndarray
        Möbius array (int8) with a dummy zero at index 0.
    start : int
        1‑based start index of the window.
    L : int
        Length of the window.
    h : int
        Lag (1 ≤ h < L).

    Returns
    -------
    float
        Normalized autocorrelation ``(1/(L‑h)) * Σ μ(k+i) μ(k+i+h)``.
    """
    if h >= L:
        raise ValueError("Lag h must be strictly smaller than window length L.")
    window = mobius[start : start + L]
    prod_sum = int(
        np.dot(
            window[: L - h].astype(np.int64),
            window[h:].astype(np.int64),
        )
    )
    return prod_sum / float(L - h)


# ----------------------------------------------------------------------
def main() -> None:
    """
    Execute the demo autocorrelation computation and write the CSV.
    The CSV contains exactly one row with columns:
    interval_start,interval_length,lag,autocorrelation
    """
    mobius = _load_mobius_array()

    demo_L = 1000
    demo_h = 1

    demo_start = _load_first_window_start(demo_L)

    autocorr_val = compute_autocorrelation(mobius, demo_start, demo_L, demo_h)

    # Verify against the hand‑computed reference (absolute tolerance 1e-9).
    if not np.isclose(autocorr_val, REFERENCE_AUTOCORR, atol=1e-9):
        raise AssertionError(
            f"Demo autocorrelation {autocorr_val:.12f} does not match reference "
            f"{REFERENCE_AUTOCORR:.12f}"
        )

    # Write the result to the required CSV location.
    _ensure_parent_dir(PROCESSED_DEMO_OUTPUT_PATH)
    with PROCESSED_DEMO_OUTPUT_PATH.open("w", newline="", encoding="utf-8") as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow(
            ["interval_start", "interval_length", "lag", "autocorrelation"]
        )
        writer.writerow(
            [demo_start, demo_L, demo_h, f"{autocorr_val:.12f}"]
        )

    print(f"Demo autocorrelation written to {PROCESSED_DEMO_OUTPUT_PATH}")

if __name__ == "__main__":
    main()
